module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

    logic [8:0] sum;
    logic [8:0] diff;

    assign sum  = {1'b0, a} + {1'b0, b};
    assign diff = {1'b0, a} - {1'b0, b};

    always_comb begin
        y     = 8'd0;
        carry = 1'b0;
        case (op)
            3'b000: begin
                y     = sum[7:0];
                carry = sum[8];
            end
            3'b001: begin
                y     = diff[7:0];
                carry = diff[8];
            end
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = ($signed(a) < $signed(b)) ? 8'd1 : 8'd0;
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: y = 8'd0;
        endcase
    end

    assign zero = (y == 8'd0);

endmodule

module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

    logic [8:0] add_s;
    logic [8:0] sub_s;
    logic       slt_v;

    always_comb begin
        add_s = {1'b0, a} + {1'b0, b};
        sub_s = {1'b0, a} - {1'b0, b};
        // Signed less-than: if sign bits differ, a negative means a < b;
        // otherwise unsigned comparison gives the correct ordering.
        if (a[7] != b[7])
            slt_v = a[7];
        else
            slt_v = (a < b);
    end

    always_comb begin
        y     = 8'd0;
        carry = 1'b0;
        case (op)
            3'b000: begin
                y     = add_s[7:0];
                carry = add_s[8];
            end
            3'b001: begin
                y     = sub_s[7:0];
                carry = sub_s[8];
            end
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = {7'd0, slt_v};
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: y = 8'd0;
        endcase
    end

    assign zero = (y == 8'd0);

endmodule

module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

    logic [8:0] sum9;

    always_comb begin
        sum9  = 9'd0;
        y     = 8'd0;
        carry = 1'b0;
        case (op)
            3'b000: begin
                sum9  = {1'b0, a} + {1'b0, b};
                y     = sum9[7:0];
                carry = sum9[8];
            end
            3'b001: begin
                y     = a - b;
                carry = (a < b);
            end
            3'b010: begin
                y     = a & b;
                carry = 1'b0;
            end
            3'b011: begin
                y     = a | b;
                carry = 1'b0;
            end
            3'b100: begin
                y     = a ^ b;
                carry = 1'b0;
            end
            3'b101: begin
                if (a[7] != b[7])
                    y = {7'd0, a[7]};
                else
                    y = {7'd0, (a < b)};
                carry = 1'b0;
            end
            3'b110: begin
                y     = a << b[2:0];
                carry = 1'b0;
            end
            3'b111: begin
                y     = a >> b[2:0];
                carry = 1'b0;
            end
            default: begin
                y     = 8'd0;
                carry = 1'b0;
            end
        endcase
    end

    assign zero = (y == 8'd0);

endmodule

module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

    logic [8:0] sum;
    logic [8:0] diff;

    assign sum  = {1'b0, a} + {1'b0, b};
    assign diff = {1'b0, a} - {1'b0, b};

    always_comb begin
        y     = 8'd0;
        carry = 1'b0;
        case (op)
            3'b000: begin
                y     = sum[7:0];
                carry = sum[8];
            end
            3'b001: begin
                y     = diff[7:0];
                carry = diff[8];
            end
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = ($signed(a) < $signed(b)) ? 8'd1 : 8'd0;
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: y = 8'd0;
        endcase
    end

    assign zero = (y == 8'd0);

endmodule

module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

    logic [8:0] add_res;
    logic [7:0] sub_res;
    logic       lt_unsigned;
    logic       lt_signed;

    assign add_res     = {1'b0, a} + {1'b0, b};
    assign sub_res     = a - b;
    assign lt_unsigned = (a < b);
    // Signed less-than: if signs differ, the negative operand is smaller;
    // otherwise unsigned comparison of the lower 7 bits gives the answer.
    assign lt_signed   = (a[7] != b[7]) ? a[7] : (a[6:0] < b[6:0]);

    always_comb begin
        y     = 8'd0;
        carry = 1'b0;
        case (op)
            3'b000: begin
                y     = add_res[7:0];
                carry = add_res[8];
            end
            3'b001: begin
                y     = sub_res;
                carry = lt_unsigned;
            end
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = {7'd0, lt_signed};
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: y = 8'd0;
        endcase
    end

    assign zero = (y == 8'd0);

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    /* verilator lint_off UNUSED */
    input  logic [2:0]  s_axi_awprot,
    /* verilator lint_on UNUSED */
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    /* verilator lint_off UNUSED */
    input  logic [2:0]  s_axi_arprot,
    /* verilator lint_on UNUSED */
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    // Write-side state
    logic        aw_full;
    logic [3:0]  aw_addr;
    logic        w_full;
    logic [31:0] w_data;
    logic [3:0]  w_strb;

    // Register state
    logic [31:0] ctrl;
    logic [31:0] scratch;
    logic [31:0] irq;

    wire [31:0] m32 = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};

    // Commit: both halves received, response not pending
    wire commit    = aw_full && w_full;
    wire commit_ok = commit && (aw_addr[1:0] == 2'b00) && (aw_addr != 4'h4);

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    // Read data mux (uses current, pre-edge register state)
    logic [31:0] rd_mux;
    always_comb begin
        case (s_axi_araddr)
            4'h0:    rd_mux = ctrl;
            4'h4:    rd_mux = status_in;
            4'h8:    rd_mux = scratch;
            4'hC:    rd_mux = irq;
            default: rd_mux = 32'd0;
        endcase
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_full      <= 1'b0;
            aw_addr      <= 4'd0;
            w_full       <= 1'b0;
            w_data       <= 32'd0;
            w_strb       <= 4'd0;
            ctrl         <= 32'd0;
            scratch      <= 32'd0;
            irq          <= 32'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else begin
            // IRQ register: set always ORed in; clear only on OKAY IRQ write commit
            if (commit_ok && aw_addr == 4'hC)
                irq <= (irq & ~(w_data & m32)) | irq_set;
            else
                irq <= irq | irq_set;

            // Write path
            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                if (commit_ok) begin
                    s_axi_bresp <= 2'b00;
                    case (aw_addr)
                        4'h0: ctrl    <= (ctrl    & ~m32) | (w_data & m32);
                        4'h8: scratch <= (scratch & ~m32) | (w_data & m32);
                        default: ;
                    endcase
                end else begin
                    s_axi_bresp <= 2'b10;
                end
            end else begin
                if (s_axi_bvalid && s_axi_bready)
                    s_axi_bvalid <= 1'b0;
                if (s_axi_awvalid && s_axi_awready) begin
                    aw_full <= 1'b1;
                    aw_addr <= s_axi_awaddr;
                end
                if (s_axi_wvalid && s_axi_wready) begin
                    w_full <= 1'b1;
                    w_data <= s_axi_wdata;
                    w_strb <= s_axi_wstrb;
                end
            end

            // Read path
            if (s_axi_rvalid && s_axi_rready)
                s_axi_rvalid <= 1'b0;
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= (s_axi_araddr[1:0] == 2'b00) ? rd_mux : 32'd0;
                s_axi_rresp  <= (s_axi_araddr[1:0] == 2'b00) ? 2'b00 : 2'b10;
            end
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    // Write request slots
    logic        aw_v;
    logic [3:0]  aw_a;
    logic        w_v;
    logic [31:0] w_d;
    logic [3:0]  w_s;

    // Registers
    logic [31:0] ctrl_r;
    logic [31:0] scratch_r;
    logic [31:0] irq_r;

    logic [31:0] bm;      // byte-expanded strobe mask
    logic [31:0] ctrl_n;
    logic [31:0] scratch_n;
    logic [31:0] irq_clr;
    logic [31:0] rd_val;

    logic        commit;
    logic        w_ok;
    logic        r_ok;
    logic        ar_ok;

    assign s_axi_awready = !aw_v && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_v  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    assign commit = aw_v && w_v;

    // Write address decode: aligned and not STATUS (0x4)
    assign w_ok = (aw_a[1:0] == 2'b00) && (aw_a[3:2] != 2'b01);

    // Read address decode validity
    assign r_ok = (s_axi_araddr[1:0] == 2'b00);

    always_comb begin
        for (int i = 0; i < 4; i++) begin
            bm[8*i +: 8] = {8{w_s[i]}};
        end
    end

    assign ctrl_n    = (ctrl_r    & ~bm) | (w_d & bm);
    assign scratch_n = (scratch_r & ~bm) | (w_d & bm);

    // IRQ clear mask: only on committed, valid IRQ write
    assign irq_clr = (commit && w_ok && (aw_a[3:2] == 2'b11)) ? (w_d & bm) : 32'd0;

    always_comb begin
        case (s_axi_araddr[3:2])
            2'b00:   rd_val = ctrl_r;
            2'b01:   rd_val = status_in;
            2'b10:   rd_val = scratch_r;
            default: rd_val = irq_r;
        endcase
        if (!r_ok || s_axi_araddr[3:2] == 2'b00 && 1'b0) rd_val = 32'd0;
    end

    // Write path state
    always_ff @(posedge clk) begin
        if (rst) begin
            aw_v          <= 1'b0;
            aw_a          <= 4'd0;
            w_v           <= 1'b0;
            w_d           <= 32'd0;
            w_s           <= 4'd0;
            s_axi_bvalid  <= 1'b0;
            s_axi_bresp   <= 2'b00;
            ctrl_r        <= 32'd0;
            scratch_r     <= 32'd0;
        end else begin
            // AW slot
            if (s_axi_awvalid && s_axi_awready) begin
                aw_v <= 1'b1;
                aw_a <= s_axi_awaddr;
            end else if (commit) begin
                aw_v <= 1'b0;
            end

            // W slot
            if (s_axi_wvalid && s_axi_wready) begin
                w_v <= 1'b1;
                w_d <= s_axi_wdata;
                w_s <= s_axi_wstrb;
            end else if (commit) begin
                w_v <= 1'b0;
            end

            // Commit
            if (commit) begin
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= w_ok ? 2'b00 : 2'b10;
                if (w_ok && aw_a[3:2] == 2'b00)
                    ctrl_r <= ctrl_n;
                if (w_ok && aw_a[3:2] == 2'b10)
                    scratch_r <= scratch_n;
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end
        end
    end

    // IRQ register: set always, clear on committed IRQ write
    always_ff @(posedge clk) begin
        if (rst)
            irq_r <= 32'd0;
        else
            irq_r <= (irq_r & ~irq_clr) | irq_set;
    end

    // Read path state
    always_ff @(posedge clk) begin
        if (rst) begin
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else if (s_axi_arvalid && s_axi_arready) begin
            s_axi_rvalid <= 1'b1;
            if (r_ok) begin
                s_axi_rdata <= rd_val;
                s_axi_rresp <= 2'b00;
            end else begin
                s_axi_rdata <= 32'd0;
                s_axi_rresp <= 2'b10;
            end
        end else if (s_axi_rvalid && s_axi_rready) begin
            s_axi_rvalid <= 1'b0;
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    localparam logic [1:0] RESP_OKAY   = 2'b00;
    localparam logic [1:0] RESP_SLVERR = 2'b10;

    // Write slots
    logic        aw_v;
    logic [3:0]  aw_a;
    logic        w_v;
    logic [31:0] w_d;
    logic [3:0]  w_s;

    // Registers
    logic [31:0] ctrl_r;
    logic [31:0] scratch_r;
    logic [31:0] irq_r;

    logic        commit;
    logic        aligned_ok_wr;
    logic [1:0]  wr_resp;
    logic [31:0] strb_mask;
    logic [31:0] clr_mask;
    logic        ctrl_we, scratch_we, irq_we;
    logic [31:0] ctrl_n, scratch_n;

    logic        ar_hs;
    logic        aw_hs;
    logic        w_hs;
    logic [31:0] rd_data;
    logic [1:0]  rd_resp;

    assign commit        = aw_v & w_v;
    assign aw_hs         = s_axi_awvalid & s_axi_awready;
    assign w_hs          = s_axi_wvalid  & s_axi_wready;
    assign ar_hs         = s_axi_arvalid & s_axi_arready;

    assign s_axi_awready = ~rst & ~aw_v & ~s_axi_bvalid;
    assign s_axi_wready  = ~rst & ~w_v  & ~s_axi_bvalid;
    assign s_axi_arready = ~rst & ~s_axi_rvalid;

    // Write decode (on commit, using slot contents)
    assign aligned_ok_wr = (aw_a[1:0] == 2'b00) && (aw_a[3:2] != 2'b01);
    assign wr_resp       = aligned_ok_wr ? RESP_OKAY : RESP_SLVERR;

    assign ctrl_we    = commit & aligned_ok_wr & (aw_a[3:2] == 2'b00);
    assign scratch_we = commit & aligned_ok_wr & (aw_a[3:2] == 2'b10);
    assign irq_we     = commit & aligned_ok_wr & (aw_a[3:2] == 2'b11);

    always_comb begin
        strb_mask[7:0]   = {8{w_s[0]}};
        strb_mask[15:8]  = {8{w_s[1]}};
        strb_mask[23:16] = {8{w_s[2]}};
        strb_mask[31:24] = {8{w_s[3]}};
    end

    assign clr_mask = irq_we ? (w_d & strb_mask) : 32'h0;

    always_comb begin
        ctrl_n    = ctrl_r;
        scratch_n = scratch_r;
        for (int i = 0; i < 4; i++) begin
            if (w_s[i]) begin
                ctrl_n   [8*i +: 8] = w_d[8*i +: 8];
                scratch_n[8*i +: 8] = w_d[8*i +: 8];
            end
        end
    end

    // Read data decode
    always_comb begin
        rd_data = 32'h0;
        rd_resp = RESP_SLVERR;
        if (s_axi_araddr[1:0] == 2'b00) begin
            case (s_axi_araddr[3:2])
                2'b00: begin rd_data = ctrl_r;    rd_resp = RESP_OKAY; end
                2'b01: begin rd_data = status_in; rd_resp = RESP_OKAY; end
                2'b10: begin rd_data = scratch_r; rd_resp = RESP_OKAY; end
                2'b11: begin rd_data = irq_r;     rd_resp = RESP_OKAY; end
                default: ;
            endcase
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_v          <= 1'b0;
            aw_a          <= 4'h0;
            w_v           <= 1'b0;
            w_d           <= 32'h0;
            w_s           <= 4'h0;
            ctrl_r        <= 32'h0;
            scratch_r     <= 32'h0;
            irq_r         <= 32'h0;
            s_axi_bvalid  <= 1'b0;
            s_axi_bresp   <= 2'b00;
            s_axi_rvalid  <= 1'b0;
            s_axi_rdata   <= 32'h0;
            s_axi_rresp   <= 2'b00;
        end else begin
            // Write address slot
            if (commit) begin
                aw_v <= 1'b0;
            end else if (aw_hs) begin
                aw_v <= 1'b1;
                aw_a <= s_axi_awaddr;
            end

            // Write data slot
            if (commit) begin
                w_v <= 1'b0;
            end else if (w_hs) begin
                w_v <= 1'b1;
                w_d <= s_axi_wdata;
                w_s <= s_axi_wstrb;
            end

            // Write response
            if (commit) begin
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= wr_resp;
            end else if (s_axi_bvalid & s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // Register updates
            if (ctrl_we)    ctrl_r    <= ctrl_n;
            if (scratch_we) scratch_r <= scratch_n;
            irq_r <= (irq_r & ~clr_mask) | irq_set;

            // Read response
            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_data;
                s_axi_rresp  <= rd_resp;
            end else if (s_axi_rvalid & s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    // Write address/data slots
    logic        aw_v;
    logic [3:0]  aw_a;
    logic        w_v;
    logic [31:0] w_d;
    logic [3:0]  w_s;

    // Registers
    logic [31:0] ctrl_r;
    logic [31:0] scratch_r;
    logic [31:0] irq_r;

    // Response state
    logic [1:0]  bresp_r;
    logic        bvalid_r;
    logic [31:0] rdata_r;
    logic [1:0]  rresp_r;
    logic        rvalid_r;

    // Handshake-derived controls
    wire aw_hs = s_axi_awvalid && s_axi_awready;
    wire w_hs  = s_axi_wvalid  && s_axi_wready;
    wire ar_hs = s_axi_arvalid && s_axi_arready;
    wire b_hs  = bvalid_r && s_axi_bready;
    wire r_hs  = rvalid_r && s_axi_rready;

    assign s_axi_awready = !aw_v && !bvalid_r && !rst;
    assign s_axi_wready  = !w_v  && !bvalid_r && !rst;
    assign s_axi_arready = !rvalid_r && !rst;

    assign s_axi_bvalid = bvalid_r;
    assign s_axi_bresp  = bresp_r;
    assign s_axi_rvalid = rvalid_r;
    assign s_axi_rdata  = rdata_r;
    assign s_axi_rresp  = rresp_r;

    // Commit decode
    wire        wr_commit = aw_v && w_v;
    wire        wr_aligned = (aw_a[1:0] == 2'b00);
    wire [1:0]  wr_idx = aw_a[3:2];
    wire        wr_ok = wr_aligned && (wr_idx != 2'd1);

    wire [31:0] wmask = {{8{w_s[3]}}, {8{w_s[2]}}, {8{w_s[1]}}, {8{w_s[0]}}};

    wire ctrl_wr    = wr_commit && wr_aligned && (wr_idx == 2'd0);
    wire scratch_wr = wr_commit && wr_aligned && (wr_idx == 2'd2);
    wire irq_wr     = wr_commit && wr_aligned && (wr_idx == 2'd3);

    // Read decode
    wire        rd_aligned = (s_axi_araddr[1:0] == 2'b00);
    wire [1:0]  rd_idx = s_axi_araddr[3:2];
    logic [31:0] rd_mux;

    always_comb begin
        case (rd_idx)
            2'd0:    rd_mux = ctrl_r;
            2'd1:    rd_mux = status_in;
            2'd2:    rd_mux = scratch_r;
            default: rd_mux = irq_r;
        endcase
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_v      <= 1'b0;
            aw_a      <= 4'd0;
            w_v       <= 1'b0;
            w_d       <= 32'd0;
            w_s       <= 4'd0;
            ctrl_r    <= 32'd0;
            scratch_r <= 32'd0;
            irq_r     <= 32'd0;
            bresp_r   <= 2'b00;
            bvalid_r  <= 1'b0;
            rdata_r   <= 32'd0;
            rresp_r   <= 2'b00;
            rvalid_r  <= 1'b0;
        end else begin
            // Write address channel
            if (aw_hs) begin
                aw_v <= 1'b1;
                aw_a <= s_axi_awaddr;
            end else if (wr_commit) begin
                aw_v <= 1'b0;
            end

            // Write data channel
            if (w_hs) begin
                w_v <= 1'b1;
                w_d <= s_axi_wdata;
                w_s <= s_axi_wstrb;
            end else if (wr_commit) begin
                w_v <= 1'b0;
            end

            // Register writes at commit
            if (ctrl_wr) begin
                ctrl_r <= (ctrl_r & ~wmask) | (w_d & wmask);
            end
            if (scratch_wr) begin
                scratch_r <= (scratch_r & ~wmask) | (w_d & wmask);
            end

            // IRQ: clear on write commit, then OR in irq_set every non-reset edge
            if (irq_wr) begin
                irq_r <= (irq_r & ~(w_d & wmask)) | irq_set;
            end else begin
                irq_r <= irq_r | irq_set;
            end

            // Write response channel
            if (wr_commit) begin
                bvalid_r <= 1'b1;
                bresp_r  <= wr_ok ? 2'b00 : 2'b10;
            end else if (b_hs) begin
                bvalid_r <= 1'b0;
            end

            // Read response channel
            if (ar_hs) begin
                rvalid_r <= 1'b1;
                if (rd_aligned) begin
                    rdata_r <= rd_mux;
                    rresp_r <= 2'b00;
                end else begin
                    rdata_r <= 32'd0;
                    rresp_r <= 2'b10;
                end
            end else if (r_hs) begin
                rvalid_r <= 1'b0;
            end
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    // Register state
    logic [31:0] ctrl_q;
    logic [31:0] scratch_q;
    logic [31:0] irq_q;

    // Write address / data slots
    logic        aw_slot_valid;
    logic [3:0]  aw_slot_addr;
    logic        w_slot_valid;
    logic [31:0] w_slot_data;
    logic [3:0]  w_slot_strb;

    // Ready / handshake signals
    assign s_axi_awready = !rst && !aw_slot_valid && !s_axi_bvalid;
    assign s_axi_wready  = !rst && !w_slot_valid && !s_axi_bvalid;
    assign s_axi_arready = !rst && !s_axi_rvalid;

    logic aw_hs, w_hs, ar_hs, b_hs, r_hs, commit;
    assign aw_hs  = s_axi_awvalid && s_axi_awready;
    assign w_hs   = s_axi_wvalid  && s_axi_wready;
    assign ar_hs  = s_axi_arvalid && s_axi_arready;
    assign b_hs   = s_axi_bvalid  && s_axi_bready;
    assign r_hs   = s_axi_rvalid  && s_axi_rready;
    assign commit = aw_slot_valid && w_slot_valid;

    // Address decode helpers
    logic addr_aligned;
    logic addr_is_status;
    logic addr_is_irq;
    assign addr_aligned  = (aw_slot_addr[1:0] == 2'b00);
    assign addr_is_status = (aw_slot_addr == 4'h4);
    assign addr_is_irq    = (aw_slot_addr == 4'hC);

    // Byte-expanded write mask for the committed write
    logic [31:0] wmask;
    always_comb begin
        for (int i = 0; i < 4; i++) begin
            wmask[8*i +: 8] = {8{w_slot_strb[i]}};
        end
    end

    // IRQ clear mask (only on IRQ write commit)
    logic [31:0] irq_clr;
    assign irq_clr = (commit && addr_is_irq) ? (w_slot_data & wmask) : 32'd0;

    // Read data mux (captured on AR handshake)
    logic [31:0] rd_mux;
    always_comb begin
        rd_mux = 32'd0;
        if (s_axi_araddr[1:0] == 2'b00) begin
            case (s_axi_araddr[3:2])
                2'd0: rd_mux = ctrl_q;
                2'd1: rd_mux = status_in;
                2'd2: rd_mux = scratch_q;
                2'd3: rd_mux = irq_q;
                default: rd_mux = 32'd0;
            endcase
        end
    end

    logic        ar_ok;
    assign ar_ok = (s_axi_araddr[1:0] == 2'b00);

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl_q        <= 32'd0;
            scratch_q     <= 32'd0;
            irq_q         <= 32'd0;
            aw_slot_valid <= 1'b0;
            aw_slot_addr  <= 4'd0;
            w_slot_valid  <= 1'b0;
            w_slot_data   <= 32'd0;
            w_slot_strb   <= 4'd0;
            s_axi_bvalid  <= 1'b0;
            s_axi_bresp   <= 2'b00;
            s_axi_rvalid  <= 1'b0;
            s_axi_rdata   <= 32'd0;
            s_axi_rresp   <= 2'b00;
        end else begin
            // Slot capture
            if (aw_hs) begin
                aw_slot_valid <= 1'b1;
                aw_slot_addr  <= s_axi_awaddr;
            end
            if (w_hs) begin
                w_slot_valid <= 1'b1;
                w_slot_data  <= s_axi_wdata;
                w_slot_strb  <= s_axi_wstrb;
            end

            // B response handshake
            if (b_hs)
                s_axi_bvalid <= 1'b0;

            // Commit edge
            if (commit) begin
                aw_slot_valid <= 1'b0;
                w_slot_valid  <= 1'b0;
                s_axi_bvalid  <= 1'b1;
                if (!addr_aligned || addr_is_status)
                    s_axi_bresp <= 2'b10;
                else
                    s_axi_bresp <= 2'b00;

                if (addr_aligned && !addr_is_status) begin
                    case (aw_slot_addr[3:2])
                        2'd0: begin
                            for (int i = 0; i < 4; i++)
                                if (w_slot_strb[i])
                                    ctrl_q[8*i +: 8] <= w_slot_data[8*i +: 8];
                        end
                        2'd2: begin
                            for (int i = 0; i < 4; i++)
                                if (w_slot_strb[i])
                                    scratch_q[8*i +: 8] <= w_slot_data[8*i +: 8];
                        end
                        default: ;
                    endcase
                end
            end

            // IRQ register: clear on write commit, OR in set pulses every edge
            irq_q <= (irq_q & ~irq_clr) | irq_set;

            // R response handshake / capture
            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_mux;
                s_axi_rresp  <= ar_ok ? 2'b00 : 2'b10;
            end else if (r_hs) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    localparam logic [31:0] POLY = 32'hEDB8_8320;
    localparam logic [31:0] INIT = 32'hFFFF_FFFF;

    logic [31:0] rem;

    // Process one byte, LSB first, starting from remainder r.
    function automatic logic [31:0] crc_byte(input logic [31:0] r_in,
                                             input logic [7:0]  d);
        logic [31:0] r;
        logic        mix;
        begin
            r = r_in;
            for (int i = 0; i < 8; i++) begin
                mix = r[0] ^ d[i];
                r   = r >> 1;
                if (mix) r = r ^ POLY;
            end
            crc_byte = r;
        end
    endfunction

    logic [31:0] base;
    logic [31:0] next_rem;

    always_comb begin
        base     = start ? INIT : rem;
        next_rem = in_valid ? crc_byte(base, data) : base;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= INIT;
            out_valid <= 1'b0;
        end else begin
            rem       <= next_rem;
            out_valid <= in_valid;
        end
    end

    assign crc = rem ^ INIT;

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem;

    function automatic logic [31:0] crc_byte(input logic [31:0] r, input logic [7:0] d);
        logic [31:0] c;
        logic        m;
        c = r;
        for (int i = 0; i < 8; i++) begin
            m = c[0] ^ d[i];
            c = c >> 1;
            if (m) c = c ^ 32'hEDB8_8320;
        end
        return c;
    endfunction

    logic [31:0] init_rem;
    logic [31:0] next_rem;

    always_comb begin
        init_rem = start ? 32'hFFFF_FFFF : rem;
        if (in_valid)
            next_rem = crc_byte(init_rem, data);
        else
            next_rem = init_rem;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= 32'hFFFF_FFFF;
            crc       <= 32'h0000_0000;
            out_valid <= 1'b0;
        end else begin
            rem       <= next_rem;
            crc       <= next_rem ^ 32'hFFFF_FFFF;
            out_valid <= in_valid;
        end
    end

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    localparam logic [31:0] CRC_INIT = 32'hFFFF_FFFF;
    localparam logic [31:0] CRC_POLY = 32'hEDB8_8320;

    logic [31:0] rem;

    // Process one byte, bit 0 first, reflected CRC-32 polynomial.
    function automatic logic [31:0] crc_byte(input logic [31:0] r, input logic [7:0] d);
        logic [31:0] c;
        logic        m;
        c = r;
        for (int unsigned i = 0; i < 8; i++) begin
            m = c[0] ^ d[i];
            c = {1'b0, c[31:1]};
            if (m) c = c ^ CRC_POLY;
        end
        return c;
    endfunction

    logic [31:0] init_rem;
    logic [31:0] next_rem;

    always_comb begin
        init_rem = start ? CRC_INIT : rem;
        next_rem = in_valid ? crc_byte(init_rem, data) : init_rem;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= CRC_INIT;
            crc       <= 32'h0000_0000;
            out_valid <= 1'b0;
        end else begin
            rem       <= next_rem;
            crc       <= next_rem ^ CRC_INIT;
            out_valid <= in_valid;
        end
    end

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem;      // internal remainder register
    logic [31:0] base;     // remainder chosen for this cycle
    logic [31:0] nxt;      // remainder after processing (if any) this cycle
    logic [31:0] c;
    logic        m;

    always_comb begin
        base = start ? 32'hFFFF_FFFF : rem;
        c    = base;
        if (in_valid) begin
            for (int unsigned i = 0; i < 8; i++) begin
                m = c[0] ^ data[i];
                c = {1'b0, c[31:1]};
                if (m) c = c ^ 32'hEDB8_8320;
            end
        end
        nxt = c;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= 32'hFFFF_FFFF;
            out_valid <= 1'b0;
        end else begin
            rem       <= nxt;
            out_valid <= in_valid;
        end
    end

    // Output is the current remainder XOR FFFF_FFFF; zero after reset.
    assign crc = rst ? 32'h0000_0000 : (rem ^ 32'hFFFF_FFFF);

endmodule

module crc32_stream (
