    always_comb begin
        init = start ? 32'hFFFF_FFFF : rem;
        nxt  = in_valid ? crc_byte(init, data) : init;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= 32'hFFFF_FFFF;
            out_valid <= 1'b0;
        end else begin
            rem       <= nxt;
            out_valid <= in_valid;
