module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    // Stage 1: capture operands (edge k)
    logic signed [WIDTH-1:0]   a_r1, b_r1;
    logic                      v1;

    // Stage 2: full product (edge k+1)
    logic signed [2*WIDTH-1:0] p_r2;
    logic                      v2;

    // Stage 3: pipelined product (edge k+2)
    logic signed [2*WIDTH-1:0] p_r3;
    logic                      v3;

    // Combinational sign-extended multiply
    logic signed [2*WIDTH-1:0] ea, eb, pm;
    assign ea = {{WIDTH{a_r1[WIDTH-1]}}, a_r1};
    assign eb = {{WIDTH{b_r1[WIDTH-1]}}, b_r1};
    assign pm = ea * eb;

    always_ff @(posedge clk) begin
        if (rst) begin
            a_r1 <= '0;
            b_r1 <= '0;
            v1   <= 1'b0;
            p_r2 <= '0;
            v2   <= 1'b0;
            p_r3 <= '0;
            v3   <= 1'b0;
            product   <= '0;
            out_valid <= 1'b0;
        end else begin
            a_r1 <= a;
            b_r1 <= b;
            v1   <= in_valid;

            p_r2 <= pm;
            v2   <= v1;

            p_r3 <= p_r2;
            v3   <= v2;

            out_valid <= v3;
            product   <= v3 ? p_r3 : '0;
        end
    end

endmodule

module mul_pipe3 #(
