);

    // Stage 1: operand capture (edge k)
    logic signed [WIDTH-1:0]   a_r, b_r;
    logic                      v1;
    // Stage 2: multiply (edge k+1)
    logic signed [2*WIDTH-1:0] prod2;
    logic                      v2;
    // Stage 3: delay (edge k+2)
    logic signed [2*WIDTH-1:0] prod3;
    logic                      v3;

    always_ff @(posedge clk) begin
        if (rst) begin
            a_r     <= '0;
            b_r     <= '0;
            v1      <= 1'b0;
            prod2   <= '0;
            v2      <= 1'b0;
            prod3   <= '0;
            v3      <= 1'b0;
            out_valid <= 1'b0;
            product <= '0;
        end else begin
            a_r     <= a;
            b_r     <= b;
            v1      <= in_valid;

            prod2   <= a_r * b_r;
            v2      <= v1;

            prod3   <= prod2;
            v3      <= v2;

            out_valid <= v3;
            product   <= v3 ? prod3 : '0;
        end
    end

endmodule

module mul_pipe3 #(
