    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    // Stage A: operand capture (edge k)
    logic signed [WIDTH-1:0]   a_r, b_r;
    logic                      v_a;

    // Stage B: multiply (edge k+1)
    logic signed [2*WIDTH-1:0] p_b;
    logic                      v_b;

    // Stage C: pipe register (edge k+2)
    logic signed [2*WIDTH-1:0] p_c;
    logic                      v_c;

    always_ff @(posedge clk) begin
        if (rst) begin
            v_a       <= 1'b0;
            v_b       <= 1'b0;
            v_c       <= 1'b0;
            out_valid <= 1'b0;
            product   <= '0;
        end else begin
            // Stage A
            a_r <= a;
            b_r <= b;
            v_a <= in_valid;

            // Stage B
            p_b <= a_r * b_r;
            v_b <= v_a;

            // Stage C
            p_c <= p_b;
            v_c <= v_b;

            // Output stage (edge k+3)
            out_valid <= v_c;
            product   <= v_c ? p_c : '0;
        end
    end

endmodule

