        if (rst) begin
            v1        <= 1'b0;
            v2        <= 1'b0;
            v3        <= 1'b0;
            out_valid <= 1'b0;
            product   <= '0;
        end else begin
            v1 <= in_valid;
            ra <= a;
            rb <= b;

            v2 <= v1;
            p2 <= ra * rb;

            v3 <= v2;
            p3 <= v2 ? p2 : '0;

            out_valid <= v3;
            product   <= v3 ? p3 : '0;
        end
    end

endmodule

module mul_pipe3 #(
