module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Lane indices: N=0, S=1, E=2, W=3, L=4
    logic [4:0]   ovalid_q;
    logic [F-1:0] oflit_q [0:4];
    logic [2:0]   osrc_q  [0:4];
    logic [2:0]   cur_q   [0:4];

    logic [2:0]   rt    [0:4];
    logic [2:0]   cur_n [0:4];
    logic [2:0]   wsrc  [0:4];
    logic [F-1:0] ch_flit [0:4];
    logic [4:0]   wv;
    logic [4:0]   xfer;
    logic [4:0]   avail;
    logic [4:0]   gnt_in;

    function automatic logic [2:0] succ(input logic [2:0] i);
        return (i == 3'd4) ? 3'd0 : i + 3'd1;
    endfunction

    // Routing computation
    always_comb begin
        logic [F-1:0] fl;
        logic [1:0]   dx;
        logic [1:0]   dy;
        for (int i = 0; i < 5; i++) begin
            fl = in_flit[i*F +: F];
            dx = fl[F-1 -: 2];
            dy = fl[F-3 -: 2];
            if (dx > X)       rt[i] = 3'd2; // E
            else if (dx < X)  rt[i] = 3'd3; // W
            else if (dy > Y)  rt[i] = 3'd0; // N
            else if (dy < Y)  rt[i] = 3'd1; // S
            else              rt[i] = 3'd4; // L
        end
    end

    // Per-output availability, cursor update, and arbitration
    always_comb begin
        int idx;
        int s;
        for (int o = 0; o < 5; o++) begin
            xfer[o]  = ovalid_q[o] & out_ready[o];
            avail[o] = ~ovalid_q[o] | out_ready[o];
            cur_n[o] = xfer[o] ? succ(osrc_q[o]) : cur_q[o];
            wv[o]    = 1'b0;
            wsrc[o]  = 3'd0;
            ch_flit[o] = '0;
            s = int'(cur_n[o]);
            for (int k = 0; k < 5; k++) begin
                idx = (s + k) % 5;
                if (!wv[o] && avail[o] && in_valid[idx] && (int'(rt[idx]) == o)) begin
                    wv[o]      = 1'b1;
                    wsrc[o]    = 3'(idx);
                    ch_flit[o] = in_flit[idx*F +: F];
                end
            end
        end
    end

    // Input ready
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            gnt_in[i] = 1'b0;
            for (int o = 0; o < 5; o++) begin
                if (wv[o] && (int'(wsrc[o]) == i))
                    gnt_in[i] = 1'b1;
            end
            in_ready[i] = gnt_in[i] & ~rst;
        end
    end

    // Output registers
    always_ff @(posedge clk) begin
        if (rst) begin
            ovalid_q <= '0;
            for (int o = 0; o < 5; o++) begin
                oflit_q[o] <= '0;
                osrc_q[o]  <= 3'd0;
                cur_q[o]   <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                cur_q[o] <= cur_n[o];
                if (wv[o]) begin
                    ovalid_q[o] <= 1'b1;
                    oflit_q[o]  <= ch_flit[o];
                    osrc_q[o]   <= wsrc[o];
                end else if (xfer[o]) begin
                    ovalid_q[o] <= 1'b0;
                    oflit_q[o]  <= '0;
                end
            end
        end
    end

    // Outputs
    assign out_valid = ovalid_q;

    always_comb begin
        for (int o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = oflit_q[o];
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
