    logic [2:0]   cur_n   [0:4];
    logic [2:0]   wsrc    [0:4];
    logic [F-1:0] ch_flit [0:4];
    logic [4:0]   wv;
    logic [4:0]   xfer;
    logic [4:0]   avail;
    logic [4:0]   gnt_in;

    function automatic logic [2:0] succ(input logic [2:0] i);
        logic [2:0] r;
        if (i == 3'd4) r = 3'd0;
        else           r = i + 3'd1;
        return r;
    endfunction

    // Routing computation
    always_comb begin
        logic [F-1:0] fl;
        logic [1:0]   dx;
        logic [1:0]   dy;
        for (int i = 0; i < 5; i++) begin
            fl = in_flit[i*F +: F];
            dx = fl[F-1 -: 2];
            dy = fl[F-3 -: 2];
            if (dx > X)       rt[i] = 3'd2; // E
            else if (dx < X)  rt[i] = 3'd3; // W
            else if (dy > Y)  rt[i] = 3'd0; // N
            else if (dy < Y)  rt[i] = 3'd1; // S
            else              rt[i] = 3'd4; // L
        end
    end

    // Per-output availability, cursor update, and arbitration
    always_comb begin
        int idx;
        int s;
        for (int o = 0; o < 5; o++) begin
