            wv[o]      = 1'b0;
            wsrc[o]    = 3'd0;
            ch_flit[o] = '0;
            s = cur_n[o];
            for (int k = 0; k < 5; k++) begin
                idx = (s + k) % 5;
                if (!wv[o] && avail[o] && in_valid[idx] && (rt[idx] == o)) begin
                    wv[o]      = 1'b1;
                    wsrc[o]    = idx[2:0];
                    ch_flit[o] = in_flit[idx*F +: F];
                end
            end
        end
    end

    // Input ready
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            gnt_in[i] = 1'b0;
            for (int o = 0; o < 5; o++) begin
                if (wv[o] && (wsrc[o] == i))
                    gnt_in[i] = 1'b1;
            end
            in_ready[i] = gnt_in[i] & ~rst;
        end
    end

    // Output registers
    always_ff @(posedge clk) begin
        if (rst) begin
            ovalid_q <= '0;
            for (int o = 0; o < 5; o++) begin
                oflit_q[o] <= '0;
                osrc_q[o]  <= 3'd0;
                cur_q[o]   <= 3'd0;
            end
