    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Lane indices: N=0, S=1, E=2, W=3, L=4
    // Output slot state (packed, with declaration initialisers so that
    // outputs read as empty/zero before the first reset edge).
    logic [4:0]     ovalid_q = '0;
    logic [5*F-1:0] oflit_q  = '0;
    logic [14:0]    osrc_q   = '0;   // 3 bits per output
    logic [14:0]    cur_q    = '0;   // 3 bits per output

    logic [14:0]    rt;              // 3 bits per input
    logic [14:0]    cur_n;           // 3 bits per output
    logic [14:0]    wsrc;            // 3 bits per output
    logic [5*F-1:0] ch_flit;
    logic [4:0]     wv;
    logic [4:0]     xfer;
    logic [4:0]     avail;
    logic [4:0]     gnt_in;

    function automatic logic [2:0] succ(input logic [2:0] i);
        logic [2:0] r;
        if (i == 3'd4) r = 3'd0;
        else           r = i + 3'd1;
        return r;
    endfunction

    // Routing computation
    always_comb begin
        logic [F-1:0] fl;
        logic [1:0]   dx;
        logic [1:0]   dy;
        logic [2:0]   r;
        for (int i = 0; i < 5; i++) begin
            fl = in_flit[i*F +: F];
            dx = fl[F-1 -: 2];
            dy = fl[F-3 -: 2];
            if (dx > X)       r = 3'd2; // E
            else if (dx < X)  r = 3'd3; // W
            else if (dy > Y)  r = 3'd0; // N
            else if (dy < Y)  r = 3'd1; // S
            else              r = 3'd4; // L
            rt[i*3 +: 3] = r;
        end
    end

    // Per-output availability, cursor, and arbitration
    always_comb begin
        int idx;
        int s;
        for (int o = 0; o < 5; o++) begin
            xfer[o]  = ovalid_q[o] & out_ready[o];
            avail[o] = ~ovalid_q[o] | out_ready[o];
            cur_n[o*3 +: 3] = xfer[o] ? succ(osrc_q[o*3 +: 3]) : cur_q[o*3 +: 3];
            wv[o]    = 1'b0;
            wsrc[o*3 +: 3]   = 3'd0;
            ch_flit[o*F +: F] = '0;
            s = cur_n[o*3 +: 3];
            for (int k = 0; k < 5; k++) begin
                idx = (s + k) % 5;
                if (!wv[o] && avail[o] && in_valid[idx] && (rt[idx*3 +: 3] == o)) begin
                    wv[o]             = 1'b1;
                    wsrc[o*3 +: 3]    = idx[2:0];
                    ch_flit[o*F +: F] = in_flit[idx*F +: F];
                end
            end
        end
    end

    // Input ready (gated by reset)
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            gnt_in[i] = 1'b0;
            for (int o = 0; o < 5; o++) begin
                if (wv[o] && (wsrc[o*3 +: 3] == i))
                    gnt_in[i] = 1'b1;
            end
            in_ready[i] = gnt_in[i] & ~rst;
        end
    end

    // Registered output slots and cursors
    always_ff @(posedge clk) begin
        if (rst) begin
            ovalid_q <= '0;
            oflit_q  <= '0;
            osrc_q   <= '0;
            cur_q    <= '0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                cur_q[o*3 +: 3] <= cur_n[o*3 +: 3];
                if (wv[o]) begin
                    ovalid_q[o]       <= 1'b1;
                    oflit_q[o*F +: F] <= ch_flit[o*F +: F];
                    osrc_q[o*3 +: 3]  <= wsrc[o*3 +: 3];
                end else if (xfer[o]) begin
                    ovalid_q[o]       <= 1'b0;
                    oflit_q[o*F +: F] <= '0;
                end
            end
        end
    end

    // Outputs
    assign out_valid = ovalid_q;
    assign out_flit  = oflit_q;

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Output slot state
    logic [F-1:0] slot [5];
    logic [4:0]   ov;
    logic [2:0]   src  [5];
    logic [2:0]   cur  [5];

    // Routing destination per input lane (N=0,S=1,E=2,W=3,L=4)
    logic [2:0] dst [5];

    // Request matrix: rq[o][i] = input i valid and requests output o
    logic [4:0] rq [5];

    // Per-output combinational arbitration
    logic       avail [5];
    logic       xfer  [5];
    logic [2:0] start [5];
    logic       gv    [5];
    logic [2:0] gi    [5];

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : (s + 3'd1);
    endfunction

    // Routing
    always_comb begin
        logic [1:0] dx;
        logic [1:0] dy;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)       dst[i] = 3'd2; // E
            else if (dx < X)  dst[i] = 3'd3; // W
            else if (dy > Y)  dst[i] = 3'd0; // N
            else if (dy < Y)  dst[i] = 3'd1; // S
            else              dst[i] = 3'd4; // L
        end
    end

    always_comb begin
        for (int o = 0; o < 5; o++) begin
            for (int i = 0; i < 5; i++) begin
                rq[o][i] = in_valid[i] && (dst[i] == o[2:0]);
            end
        end
    end

    // Availability, transfer, and scan start
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            avail[o] = !ov[o] || out_ready[o];
            xfer[o]  = ov[o] && out_ready[o];
            start[o] = xfer[o] ? succ(src[o]) : cur[o];
        end
    end

    // Cyclic arbitration
    always_comb begin
        integer s;
        integer idx;
        logic   found;
        for (int o = 0; o < 5; o++) begin
            gv[o]    = 1'b0;
            gi[o]    = 3'd0;
            found    = 1'b0;
            s        = int'(start[o]);
            for (int k = 0; k < 5; k++) begin
                idx = (s + k) % 5;
                if (!found && rq[o][idx]) begin
                    found = 1'b1;
                    gv[o] = 1'b1;
                    gi[o] = idx[2:0];
                end
            end
        end
    end

    // Input ready
    always_comb begin
        in_ready = 5'b0;
        for (int o = 0; o < 5; o++) begin
            if (avail[o] && gv[o])
                in_ready[gi[o]] = 1'b1;
        end
        if (rst)
            in_ready = 5'b0;
    end

    // Registered state
    always_ff @(posedge clk) begin
        if (rst) begin
            ov <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                cur[o] <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                cur[o] <= start[o];
                if (avail[o] && gv[o]) begin
                    ov[o]   <= 1'b1;
                    slot[o] <= in_flit[gi[o]*F +: F];
                    src[o]  <= gi[o];
                end else if (xfer[o]) begin
                    ov[o] <= 1'b0;
                end
            end
        end
    end

    // Outputs
    always_comb begin
        out_valid = ov;
        for (int o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = ov[o] ? slot[o] : {F{1'b0}};
        end
    end

endmodule

