module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Output slot state
    logic [F-1:0] flit_q [5];
    logic [4:0]   valid_q;
    logic [2:0]   src_q  [5];
    logic [2:0]   cur_q  [5];

    // Routing / arbitration
    logic [2:0]   route    [5];
    logic [4:0]   req      [5];
    logic [4:0]   avail;
    logic [4:0]   xfer;
    logic [2:0]   start    [5];
    logic [4:0]   chosen_v;
    logic [2:0]   chosen_i [5];

    function automatic logic [2:0] route_fn(input logic [F-1:0] f);
        logic [1:0] dx;
        logic [1:0] dy;
        dx = f[F-1 -: 2];
        dy = f[F-3 -: 2];
        if (dx > X)       return 3'd2; // E
        else if (dx < X)  return 3'd3; // W
        else if (dy > Y)  return 3'd0; // N
        else if (dy < Y)  return 3'd1; // S
        else              return 3'd4; // L
    endfunction

    function automatic logic [2:0] succ(input logic [2:0] s);
        if (s == 3'd4) return 3'd0;
        else           return s + 3'd1;
    endfunction

    assign avail = ~valid_q | out_ready;
    assign xfer  = valid_q & out_ready;

    always_comb begin
        int idx;
        int k;
        logic [2:0] st;
        for (int i = 0; i < 5; i++) begin
            route[i] = route_fn(in_flit[i*F +: F]);
        end
        for (int j = 0; j < 5; j++) begin
            for (int i = 0; i < 5; i++) begin
                req[j][i] = in_valid[i] && (route[i] == 3'(j));
            end
        end
        for (int j = 0; j < 5; j++) begin
            chosen_v[j] = 1'b0;
            chosen_i[j] = 3'd0;
            st = xfer[j] ? succ(src_q[j]) : cur_q[j];
            start[j] = st;
            // Iterate in reverse so the lowest k (highest priority) wins.
            for (k = 4; k >= 0; k--) begin
                idx = (int'(st) + k) % 5;
                if (req[j][idx]) begin
                    chosen_v[j] = 1'b1;
                    chosen_i[j] = 3'(idx);
                end
            end
        end
    end

    always_comb begin
        in_ready = '0;
        for (int j = 0; j < 5; j++) begin
            if (!rst && avail[j] && chosen_v[j]) begin
                in_ready[chosen_i[j]] = 1'b1;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            valid_q <= '0;
            for (int j = 0; j < 5; j++) begin
                cur_q[j]  <= 3'd0;
                src_q[j]  <= 3'd0;
                flit_q[j] <= '0;
            end
        end else begin
            for (int j = 0; j < 5; j++) begin
                if (avail[j]) begin
                    valid_q[j] <= chosen_v[j];
                end
                if (avail[j] && chosen_v[j]) begin
                    flit_q[j] <= in_flit[int'(chosen_i[j])*F +: F];
                    src_q[j]  <= chosen_i[j];
                end
                cur_q[j] <= start[j];
            end
        end
    end

    assign out_valid = valid_q;

    genvar g;
    generate
        for (g = 0; g < 5; g++) begin : g_out
            assign out_flit[g*F +: F] = valid_q[g] ? flit_q[g] : '0;
        end
    endgenerate

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Packed state: slot j occupies bits [j*W +: W]
    logic [5*F-1:0] flit_q;
    logic [4:0]     valid_q;
    logic [14:0]    src_q;      // 5 x 3 bits
    logic [14:0]    cur_q;      // 5 x 3 bits

    // Routing and arbitration
    logic [14:0]    route_p;    // 5 x 3 bits, requested output per input
    logic [24:0]    req_p;      // req_p[j*5+i]: input i requests output j
    logic [4:0]     avail;
    logic [4:0]     xfer;
    logic [14:0]    start_p;    // 5 x 3 bits
    logic [4:0]     chosen_v;
    logic [14:0]    chosen_p;   // 5 x 3 bits

    // Route computation per input
    genvar gi;
    generate
        for (gi = 0; gi < 5; gi++) begin : g_route
            logic [1:0] dx;
            logic [1:0] dy;
            logic [2:0] r;
            assign dx = in_flit[gi*F + F-1 -: 2];
            assign dy = in_flit[gi*F + F-3 -: 2];
            always_comb begin
                if (dx > X)       r = 3'd2; // E
                else if (dx < X)  r = 3'd3; // W
                else if (dy > Y)  r = 3'd0; // N
                else if (dy < Y)  r = 3'd1; // S
                else              r = 3'd4; // L
            end
            assign route_p[gi*3 +: 3] = r;
        end
    endgenerate

    // Request matrix
    genvar gj, gk;
    generate
        for (gj = 0; gj < 5; gj++) begin : g_reqj
            for (gk = 0; gk < 5; gk++) begin : g_reqi
                assign req_p[gj*5 + gk] = in_valid[gk] &&
                                          (route_p[gk*3 +: 3] == 3'(gj));
            end
        end
    endgenerate

    assign avail = ~valid_q | out_ready;
    assign xfer  = valid_q & out_ready;

    // Cyclic priority scan starting from the per-output cursor
    always_comb begin
        int idx;
        logic [2:0] sst;
        logic [2:0] succ_s;
        logic [2:0] cur_s;
        logic [2:0] src_s;
        for (int j = 0; j < 5; j++) begin
            cur_s = cur_q[j*3 +: 3];
            src_s = src_q[j*3 +: 3];
            if (src_s == 3'd4) succ_s = 3'd0;
            else               succ_s = src_s + 3'd1;
            sst = xfer[j] ? succ_s : cur_s;
            start_p[j*3 +: 3] = sst;
            chosen_v[j] = 1'b0;
            chosen_p[j*3 +: 3] = 3'd0;
            // Reverse order so the lowest offset (highest priority) wins.
            for (int k = 4; k >= 0; k--) begin
                idx = (int'(sst) + k) % 5;
                if (req_p[j*5 + idx]) begin
                    chosen_v[j] = 1'b1;
                    chosen_p[j*3 +: 3] = 3'(idx);
                end
            end
        end
    end

    // Input ready: only the chosen input of an available output
    always_comb begin
        in_ready = 5'b0;
        for (int j = 0; j < 5; j++) begin
            if (!rst && avail[j] && chosen_v[j]) begin
                in_ready[int'(chosen_p[j*3 +: 3])] = 1'b1;
            end
        end
    end

    // State update
    always_ff @(posedge clk) begin
        if (rst) begin
            valid_q <= 5'b0;
            cur_q   <= 15'b0;
            src_q   <= 15'b0;
            flit_q  <= '0;
        end else begin
            for (int j = 0; j < 5; j++) begin
                if (avail[j]) begin
                    valid_q[j] <= chosen_v[j];
                end
                if (avail[j] && chosen_v[j]) begin
                    flit_q[j*F +: F] <= in_flit[int'(chosen_p[j*3 +: 3])*F +: F];
                    src_q[j*3 +: 3]  <= chosen_p[j*3 +: 3];
                end
                cur_q[j*3 +: 3] <= start_p[j*3 +: 3];
            end
        end
    end

    // Outputs: registered slots, zero flit when invalid
    assign out_valid = valid_q;

    genvar go;
    generate
        for (go = 0; go < 5; go++) begin : g_out
            assign out_flit[go*F +: F] = valid_q[go] ? flit_q[go*F +: F] : {F{1'b0}};
        end
    endgenerate

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Packed state: slot j occupies bits [j*W +: W]
    logic [5*F-1:0] flit_q;
    logic [4:0]     valid_q;
    logic [14:0]    src_q;      // 5 x 3 bits
    logic [14:0]    cur_q;      // 5 x 3 bits

    // Routing and arbitration
    logic [14:0]    route_p;    // 5 x 3 bits, requested output per input
    logic [24:0]    req_p;      // req_p[j*5+i]: input i requests output j
    logic [4:0]     avail;
    logic [4:0]     xfer;
    logic [14:0]    start_p;    // 5 x 3 bits
    logic [4:0]     chosen_v;
    logic [14:0]    chosen_p;   // 5 x 3 bits

    // Route computation per input
    genvar gi;
    generate
        for (gi = 0; gi < 5; gi++) begin : g_route
            logic [1:0] dx;
            logic [1:0] dy;
            logic [2:0] r;
            assign dx = in_flit[gi*F + F-1 -: 2];
            assign dy = in_flit[gi*F + F-3 -: 2];
            always_comb begin
                if (dx > X)       r = 3'd2; // E
                else if (dx < X)  r = 3'd3; // W
                else if (dy > Y)  r = 3'd0; // N
                else if (dy < Y)  r = 3'd1; // S
                else              r = 3'd4; // L
            end
            assign route_p[gi*3 +: 3] = r;
        end
    endgenerate

    // Request matrix
    genvar gj, gk;
    generate
        for (gj = 0; gj < 5; gj++) begin : g_reqj
            for (gk = 0; gk < 5; gk++) begin : g_reqi
                assign req_p[gj*5 + gk] = in_valid[gk] &&
                                          (route_p[gk*3 +: 3] == gj);
            end
        end
    endgenerate

    assign avail = ~valid_q | out_ready;
    assign xfer  = valid_q & out_ready;

    // Cyclic priority scan starting from the per-output cursor
    always_comb begin
        int idx;
        logic [2:0] sst;
        logic [2:0] succ_s;
        logic [2:0] cur_s;
        logic [2:0] src_s;
        for (int j = 0; j < 5; j++) begin
            cur_s = cur_q[j*3 +: 3];
            src_s = src_q[j*3 +: 3];
            if (src_s == 3'd4) succ_s = 3'd0;
            else               succ_s = src_s + 3'd1;
            sst = xfer[j] ? succ_s : cur_s;
            start_p[j*3 +: 3] = sst;
            chosen_v[j] = 1'b0;
            chosen_p[j*3 +: 3] = 3'd0;
            // Reverse order so the lowest offset (highest priority) wins.
            for (int k = 4; k >= 0; k--) begin
                idx = (sst + k) % 5;
                if (req_p[j*5 + idx]) begin
                    chosen_v[j] = 1'b1;
                    chosen_p[j*3 +: 3] = idx[2:0];
                end
            end
        end
    end

    // Input ready: only the chosen input of an available output
    always_comb begin
        in_ready = 5'b0;
        for (int j = 0; j < 5; j++) begin
            if (!rst && avail[j] && chosen_v[j]) begin
                in_ready[chosen_p[j*3 +: 3]] = 1'b1;
            end
        end
    end

    // State update
    always_ff @(posedge clk) begin
        if (rst) begin
            valid_q <= 5'b0;
            cur_q   <= 15'b0;
            src_q   <= 15'b0;
            flit_q  <= '0;
        end else begin
            for (int j = 0; j < 5; j++) begin
                if (avail[j]) begin
                    valid_q[j] <= chosen_v[j];
                end
                if (avail[j] && chosen_v[j]) begin
                    flit_q[j*F +: F] <= in_flit[chosen_p[j*3 +: 3] * F +: F];
                    src_q[j*3 +: 3]  <= chosen_p[j*3 +: 3];
                end
                cur_q[j*3 +: 3] <= start_p[j*3 +: 3];
            end
        end
    end

    // Outputs: registered slots, zero flit when invalid
    assign out_valid = valid_q;

    genvar go;
    generate
        for (go = 0; go < 5; go++) begin : g_out
            assign out_flit[go*F +: F] = valid_q[go] ? flit_q[go*F +: F] : {F{1'b0}};
        end
    endgenerate

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;
    typedef logic [F-1:0] flit_t;

    // Output slot state
    logic [4:0]  ov;
    flit_t       of   [5];
    int          osrc [5];
    int          cur  [5];

    // Combinational signals
    int          req  [5];   // requested output for each input
    logic [4:0]  avail;
    logic [4:0]  drain;
    int          cs   [5];   // effective cursor for arbitration this edge
    logic [4:0]  sel_v;
    int          sel_i[5];
    logic [4:0]  rdy_raw;

    function automatic int route(input logic [1:0] dx, input logic [1:0] dy);
        if (dx > X)       return 2; // E
        else if (dx < X)  return 3; // W
        else if (dy > Y)  return 0; // N
        else if (dy < Y)  return 1; // S
        else              return 4; // L
    endfunction

    // Routing of each input lane
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            req[i] = route(in_flit[i*F + F - 1 -: 2], in_flit[i*F + F - 3 -: 2]);
        end
    end

    // Availability, drain, and effective cursor
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            drain[o] = ov[o] & out_ready[o];
            avail[o] = ~ov[o] | out_ready[o];
            if (drain[o]) begin
                cs[o] = (osrc[o] == 4) ? 0 : osrc[o] + 1;
            end else begin
                cs[o] = cur[o];
            end
        end
    end

    // Cyclic arbitration per output
    always_comb begin
        int idx;
        for (int o = 0; o < 5; o++) begin
            sel_v[o] = 1'b0;
            sel_i[o] = 0;
            for (int k = 0; k < 5; k++) begin
                idx = (cs[o] + k) % 5;
                if (!sel_v[o] && avail[o] && in_valid[idx] && (req[idx] == o)) begin
                    sel_v[o] = 1'b1;
                    sel_i[o] = idx;
                end
            end
        end
    end

    // Input ready
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            rdy_raw[i] = 1'b0;
            for (int o = 0; o < 5; o++) begin
                if (sel_v[o] && (sel_i[o] == i))
                    rdy_raw[i] = 1'b1;
            end
        end
        in_ready = rst ? 5'b0 : rdy_raw;
    end

    // Registered state
    always_ff @(posedge clk) begin
        if (rst) begin
            ov <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                cur[o] <= 0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                cur[o] <= cs[o];
                if (sel_v[o]) begin
                    ov[o]   <= 1'b1;
                    of[o]   <= in_flit[sel_i[o]*F +: F];
                    osrc[o] <= sel_i[o];
                end else if (drain[o]) begin
                    ov[o] <= 1'b0;
                end
            end
        end
    end

    // Outputs
    always_comb begin
        out_valid = ov;
        for (int o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = ov[o] ? of[o] : '0;
        end
    end

endmodule

module noc_router5 #(
