        if (dx > X)       return 3'd2; // E
        else if (dx < X)  return 3'd3; // W
        else if (dy > Y)  return 3'd0; // N
        else if (dy < Y)  return 3'd1; // S
        else              return 3'd4; // L
    endfunction

    // Cyclic scan starting at 'start'; returns {found, index}
    function automatic logic [3:0] pick(input logic [2:0] start,
                                        input logic [4:0] iv,
                                        input logic [4:0][2:0] rq,
                                        input logic [2:0] o);
        logic [3:0] res;
        int         t;
        logic [2:0] tl;
        res = 4'd0;
        for (int k = 0; k < 5; k++) begin
            t  = (int'(start) + k) % 5;
            tl = t[2:0];
            if (!res[3] && iv[tl] && (rq[tl] == o))
