    endfunction

    // Routing of each input lane
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            req[i] = route(in_flit[i*F + F - 1 -: 2], in_flit[i*F + F - 3 -: 2]);
        end
    end

    // Availability, drain, and effective cursor
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            drain[o] = ov[o] & out_ready[o];
