    // Per-output arbitration
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            pres[o]  = pick(cs[o], in_valid, req, o[2:0]);
            sel_v[o] = pres[o][3] & avail[o];
            sel_i[o] = pres[o][2:0];
        end
    end

    // Input ready
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            rdy_raw[i] = 1'b0;
            for (int o = 0; o < 5; o++) begin
                if (sel_v[o] && (sel_i[o] == i[2:0]))
                    rdy_raw[i] = 1'b1;
            end
        end
        in_ready = rst ? 5'b0 : rdy_raw;
    end

    // Registered state
    always_ff @(posedge clk) begin
        if (rst) begin
            ov  <= 5'b0;
            cur <= '0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                cur[o] <= cs[o];
                if (sel_v[o]) begin
                    ov[o]   <= 1'b1;
                    of[o]   <= in_flit[sel_i[o]*F +: F];
                    osrc[o] <= sel_i[o];
                end else if (drain[o]) begin
                    ov[o] <= 1'b0;
                end
            end
        end
    end

    // Outputs
    always_comb begin
        out_valid = ov;
        for (int o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = ov[o] ? of[o] : '0;
        end
    end

