    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Lane encoding: 0=N, 1=S, 2=E, 3=W, 4=L

    // Registered state
    logic [4:0]   valid_q;
    logic [F-1:0] flit_q [0:4];
    logic [2:0]   src_q  [0:4];
    logic [2:0]   cur_q  [0:4];

    // Combinational signals
    logic [2:0]   req     [0:4];
    logic [4:0]   drain;
    logic [4:0]   avail;
    logic [2:0]   cur_eff [0:4];
    logic [4:0]   sel_v;
    logic [2:0]   sel_i   [0:4];

    function automatic logic [2:0] route_f(input logic [F-1:0] f);
        logic [1:0] dx;
        logic [1:0] dy;
        logic [2:0] r;
        dx = f[F-1 -: 2];
        dy = f[F-3 -: 2];
        if (dx > X)       r = 3'd2; // E
        else if (dx < X)  r = 3'd3; // W
        else if (dy > Y)  r = 3'd0; // N
        else if (dy < Y)  r = 3'd1; // S
        else              r = 3'd4; // L
        return r;
    endfunction

    function automatic logic [2:0] succ_f(input logic [2:0] s);
        logic [2:0] r;
        if (s == 3'd4) r = 3'd0;
        else           r = s + 3'd1;
        return r;
    endfunction

    always_comb begin : comb_blk
        int c;
        int t;
        int o;
        int j;
        int k;
        for (int i = 0; i < 5; i++) begin
            req[i] = route_f(in_flit[i*F +: F]);
        end

        for (o = 0; o < 5; o++) begin
            drain[o]   = valid_q[o] & out_ready[o];
            avail[o]   = (~valid_q[o]) | out_ready[o];
            cur_eff[o] = drain[o] ? succ_f(src_q[o]) : cur_q[o];
        end

        for (o = 0; o < 5; o++) begin
            sel_v[o] = 1'b0;
            sel_i[o] = 3'd0;
            c = cur_eff[o];
            if (avail[o]) begin
                for (k = 0; k < 5; k++) begin
                    t = c + k;
                    if (t >= 5) t = t - 5;
                    if ((sel_v[o] == 1'b0) && (in_valid[t] == 1'b1) && (req[t] == o[2:0])) begin
                        sel_v[o] = 1'b1;
                        sel_i[o] = t[2:0];
                    end
                end
            end
        end

        for (j = 0; j < 5; j++) begin
            in_ready[j] = 1'b0;
            for (o = 0; o < 5; o++) begin
                if (sel_v[o] && (sel_i[o] == j[2:0]))
                    in_ready[j] = 1'b1;
            end
            if (rst) in_ready[j] = 1'b0;
        end

        out_valid = valid_q;
        for (o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = valid_q[o] ? flit_q[o] : {F{1'b0}};
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            valid_q <= 5'd0;
            for (int o = 0; o < 5; o++) begin
                cur_q[o] <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (sel_v[o]) begin
                    valid_q[o] <= 1'b1;
                    flit_q[o]  <= in_flit[sel_i[o]*F +: F];
                    src_q[o]   <= sel_i[o];
                end else if (drain[o]) begin
                    valid_q[o] <= 1'b0;
                end
                if (drain[o]) begin
                    cur_q[o] <= succ_f(src_q[o]);
                end
            end
        end
