module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);

    logic [1:0] s1 [8];
    logic [2:0] s2 [4];
    logic [3:0] s3 [2];

    always_comb begin
        for (int i = 0; i < 8; i++) begin
            s1[i] = {1'b0, x[2*i]} + {1'b0, x[2*i+1]};
        end
        for (int j = 0; j < 4; j++) begin
            s2[j] = {1'b0, s1[2*j]} + {1'b0, s1[2*j+1]};
        end
        for (int k = 0; k < 2; k++) begin
            s3[k] = {1'b0, s2[2*k]} + {1'b0, s2[2*k+1]};
        end
        count = {1'b0, s3[0]} + {1'b0, s3[1]};
    end

endmodule

