    logic [3:0] p3 [0:1];

    always_comb begin
        for (int i = 0; i < 8; i++) begin
            p1[i] = {1'b0, x[2*i]} + {1'b0, x[2*i+1]};
        end
        for (int i = 0; i < 4; i++) begin
            p2[i] = {1'b0, p1[2*i]} + {1'b0, p1[2*i+1]};
        end
        for (int i = 0; i < 2; i++) begin
            p3[i] = {1'b0, p2[2*i]} + {1'b0, p2[2*i+1]};
        end
        count = {1'b0, p3[0]} + {1'b0, p3[1]};
    end

endmodule

