module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [3:0] nxt_gnt;
    logic [1:0] nxt_last;
    logic [1:0] idx;

    always_comb begin
        nxt_gnt  = 4'b0;
        nxt_last = last;
        // Iterate from highest offset to lowest so that the earliest
        // offset (first in round-robin order) is applied last and wins.
        for (int k = 3; k >= 0; k--) begin
            idx = last + 2'(k + 1);
            if (req[idx]) begin
                nxt_gnt  = 4'b1 << idx;
                nxt_last = idx;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0;
            last <= 2'd3;
        end else begin
            gnt  <= nxt_gnt;
            last <= nxt_last;
        end
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [1:0] win;

    // Find first requester in order last+1, last+2, last+3, last+4 (mod 4).
    // Iterate from lowest priority (k=4 -> last) to highest (k=1 -> last+1),
    // so the final assignment is the highest-priority match.
    always_comb begin
        win = last;
        for (int k = 4; k >= 1; k--) begin
            if (req[last + 2'(k)])
                win = last + 2'(k);
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else if (req == 4'b0000) begin
            gnt  <= 4'b0000;
        end else begin
            gnt  <= 4'b0001 << win;
            last <= win;
        end
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [3:0] next_gnt;
    logic [1:0] next_last;

    // Combinational round-robin search: candidates last+1, last+2, last+3, last+4
    always_comb begin
        logic [1:0] idx;
        logic       found;
        next_gnt  = 4'b0000;
        next_last = last;
        found     = 1'b0;
        for (int k = 1; k <= 4; k++) begin
            idx = last + k[1:0];
            if (!found && req[idx]) begin
                found     = 1'b1;
                next_gnt  = 4'b1 << idx;
                next_last = idx;
            end
        end
    end

    // Registered grant and last-granted index
    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else if (req == 4'b0000) begin
            gnt  <= 4'b0000;
            last <= last;
        end else begin
            gnt  <= next_gnt;
            last <= next_last;
        end
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [1:0] nxt;
    logic [1:0] idx;
    logic       found;
    logic [3:0] gnt_nxt;

    always_comb begin
        nxt   = last;
        found = 1'b0;
        idx   = 2'd0;
        for (int k = 1; k <= 4; k++) begin
            idx = last + 2'(k);   // 2-bit wrap gives modulo 4
            if (!found && req[idx]) begin
                found = 1'b1;
                nxt   = idx;
            end
        end
        gnt_nxt = found ? (4'b0001 << nxt) : 4'b0000;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else begin
            gnt <= gnt_nxt;
            if (found)
                last <= nxt;
        end
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [3:0] gnt_n;
    logic [1:0] last_n;

    always_comb begin
        logic       found;
        logic [1:0] idx;
        found  = 1'b0;
        gnt_n  = 4'b0000;
        last_n = last;
        for (int k = 0; k < 4; k++) begin
            idx = last + 2'(k + 1);
            if (!found && req[idx]) begin
                found  = 1'b1;
                gnt_n  = 4'b0001 << idx;
                last_n = idx;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else begin
            gnt  <= gnt_n;
            last <= last_n;
        end
    end

endmodule

module seq_detect_1011 (
    input  logic clk,
    input  logic rst,    // synchronous, active high
    input  logic din,    // serial input, one bit per clock
    output logic match
);

    // hist holds the last three sampled bits, oldest in hist[2].
    logic [2:0] hist;

    always_ff @(posedge clk) begin
        if (rst) begin
            hist  <= 3'b000;
            match <= 1'b0;
        end else begin
            hist  <= {hist[1:0], din};
            match <= (hist == 3'b101) && din;
        end
    end

endmodule

