module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CW = (CLKS_PER_BIT > 1) ? $clog2(CLKS_PER_BIT) : 1;

    logic [9:0]    frame;   // {stop, data[7:0], start}
    logic [3:0]    bidx;    // index of bit currently on tx (0..9)
    logic [CW-1:0] cnt;     // clock cycles elapsed in current bit

    always_ff @(posedge clk) begin
        if (rst) begin
            tx    <= 1'b1;
            busy  <= 1'b0;
            frame <= 10'h3FF;
            bidx  <= 4'd0;
            cnt   <= '0;
        end else if (!busy) begin
            if (start) begin
                frame <= {1'b1, data, 1'b0};
                tx    <= 1'b0;      // start bit
                busy  <= 1'b1;
                bidx  <= 4'd0;
                cnt   <= '0;
            end
        end else begin
            if (cnt == CW'(CLKS_PER_BIT - 1)) begin
                cnt <= '0;
                if (bidx == 4'd9) begin
                    // stop bit finished: end frame
                    busy <= 1'b0;
                    tx   <= 1'b1;
                    bidx <= 4'd0;
                end else begin
                    bidx <= bidx + 4'd1;
                    tx   <= frame[bidx + 4'd1];
                end
            end else begin
                cnt <= cnt + CW'(1);
            end
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CW = (CLKS_PER_BIT > 1) ? $clog2(CLKS_PER_BIT) : 1;

    logic [CW-1:0] cnt;     // cycle index within current bit
    logic [3:0]    idx;     // 0 = start bit, 1..8 = data bits, 9 = stop bit
    logic [7:0]    shreg;   // captured data

    always_ff @(posedge clk) begin
        if (rst) begin
            tx    <= 1'b1;
            busy  <= 1'b0;
            cnt   <= '0;
            idx   <= '0;
            shreg <= '0;
        end else if (!busy) begin
            if (start) begin
                tx    <= 1'b0;
                busy  <= 1'b1;
                cnt   <= '0;
                idx   <= '0;
                shreg <= data;
            end
        end else begin
            if (cnt == CW'(CLKS_PER_BIT - 1)) begin
                cnt <= '0;
                if (idx == 4'd9) begin
                    busy <= 1'b0;
                    tx   <= 1'b1;
                    idx  <= '0;
                end else begin
                    idx <= idx + 4'd1;
                    // Next bit: idx 0..7 -> data[idx]; idx 8 -> stop bit (1)
                    if (idx < 4'd8)
                        tx <= shreg[idx[2:0]];
                    else
                        tx <= 1'b1;
                end
            end else begin
                cnt <= cnt + CW'(1);
            end
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CW = (CLKS_PER_BIT > 1) ? $clog2(CLKS_PER_BIT) : 1;

    logic [CW-1:0] cnt;      // clock cycles elapsed within current bit
    logic [3:0]    bidx;     // 0 = start bit, 1..8 = data bits, 9 = stop bit
    logic [7:0]    shreg;    // captured data, shifted out LSB first

    always_ff @(posedge clk) begin
        if (rst) begin
            tx    <= 1'b1;
            busy  <= 1'b0;
            cnt   <= '0;
            bidx  <= '0;
            shreg <= '0;
        end else if (!busy) begin
            if (start) begin
                tx    <= 1'b0;          // start bit
                busy  <= 1'b1;
                cnt   <= '0;
                bidx  <= '0;
                shreg <= data;
            end
        end else begin
            if (cnt == CW'(CLKS_PER_BIT - 1)) begin
                cnt  <= '0;
                bidx <= bidx + 4'd1;
                if (bidx == 4'd9) begin
                    // stop bit finished: end frame
                    busy <= 1'b0;
                    tx   <= 1'b1;
                end else if (bidx == 4'd8) begin
                    // move to stop bit
                    tx <= 1'b1;
                end else begin
                    // bidx 0..7 -> send data bit (bidx+1 - 1), shift next bit in
                    tx    <= shreg[0];
                    shreg <= {1'b0, shreg[7:1]};
                end
            end else begin
                cnt <= cnt + CW'(1);
            end
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    int          cnt;   // clock cycles elapsed within current bit
    logic [3:0]  idx;   // 0 = start, 1..8 = data bits, 9 = stop
    logic [7:0]  sh;    // shift register holding remaining data bits

    always_ff @(posedge clk) begin
        if (rst) begin
            tx   <= 1'b1;
            busy <= 1'b0;
            cnt  <= 0;
            idx  <= 4'd0;
            sh   <= 8'd0;
        end else if (!busy) begin
            if (start) begin
                tx   <= 1'b0;
                busy <= 1'b1;
                cnt  <= 0;
                idx  <= 4'd0;
                sh   <= data;
            end
        end else begin
            if (cnt == CLKS_PER_BIT - 1) begin
                cnt <= 0;
                if (idx == 4'd9) begin
                    // end of stop bit
                    busy <= 1'b0;
                    tx   <= 1'b1;
                end else begin
                    idx <= idx + 4'd1;
                    if (idx == 4'd8) begin
                        // next bit is stop bit
                        tx <= 1'b1;
                    end else begin
                        // next bit is data bit (LSB first)
                        tx <= sh[0];
                        sh <= sh >> 1;
                    end
                end
            end else begin
                cnt <= cnt + 1;
            end
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CW = $clog2(CLKS_PER_BIT);

    logic [CW-1:0] cnt;     // cycle counter within current bit
    logic [3:0]    idx;     // 0 = start bit, 1..8 = data bits, 9 = stop bit
    logic [7:0]    shreg;   // remaining data bits, LSB is next to send

    always_ff @(posedge clk) begin
        if (rst) begin
            tx    <= 1'b1;
            busy  <= 1'b0;
            cnt   <= '0;
            idx   <= '0;
            shreg <= '0;
        end else if (!busy) begin
            if (start) begin
                tx    <= 1'b0;
                busy  <= 1'b1;
                cnt   <= '0;
                idx   <= '0;
                shreg <= data;
            end
        end else begin
            if (cnt == CW'(CLKS_PER_BIT - 1)) begin
                cnt <= '0;
                if (idx == 4'd9) begin
                    busy <= 1'b0;
                    tx   <= 1'b1;
                    idx  <= '0;
                end else begin
                    idx <= idx + 4'd1;
                    if (idx == 4'd8) begin
                        tx <= 1'b1;            // stop bit
                    end else begin
                        tx    <= shreg[0];     // next data bit
                        shreg <= {1'b0, shreg[7:1]};
                    end
                end
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
    end

endmodule

module up_down_counter (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic       en,
    input  logic       up,    // 1 = count up, 0 = count down
    input  logic       load,
    input  logic [7:0] d,
    output logic [7:0] q
);

    always_ff @(posedge clk) begin
        if (rst)
            q <= 8'd0;
        else if (load)
            q <= d;
        else if (en)
            q <= up ? q + 8'd1 : q - 8'd1;
    end

endmodule

